import tempfile
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/write_temp')
def write_results():
    results = request.args.get('results')

    try:
        if results is None:
            raise ValueError("Results parameter is required.")

        if len(results.encode('utf-8')) > 1024 * 1024:
            raise ValueError("Input 'results' must not exceed 1MB.")

        temp_file = tempfile.NamedTemporaryFile(delete=False, dir='/tmp/')
        temp_file_path = os.path.abspath(temp_file.name)

        if not temp_file_path.startswith('/tmp/'):
            raise ValueError("Output path must be within allowed paths.")

        file_extension = os.path.splitext(temp_file_path)[1]
        if file_extension not in ['.txt', '.log']:
            raise ValueError("File must only have allowed extensions: .txt or .log.")

        temp_file.write(results.encode('utf-8'))
        temp_file.close()

        return jsonify({'file_path': temp_file_path}), 200

    except ValueError as ve:
        return jsonify({'error': str(ve)}), 400
    except OSError as oe:
        app.logger.error(f"OSError: {oe}")
        return jsonify({'error': 'Failed to create temporary file.'}), 500

