app = Flask(__name__)

@app.route('/get_average_score')
def get_average_score():
    try:
        total_score = request.args.get('total_score')
        total_count = request.args.get('total_count')
        
        if total_score is None or total_count is None:
            abort(400, description="Input values for total_score and total_count must be present")

        total_score = float(total_score)
        total_count = float(total_count)

        if not (isinstance(total_score, (int, float)) and isinstance(total_count, (int, float))):
            abort(400, description="Input values must be numeric")
        
        if not (0 <= total_score <= 1000000 and 0 <= total_count <= 1000000):
            abort(400, description="Input values must be within defined limits")
        
        average_score = total_score / total_count if total_count != 0 else abort(400, description="Division by zero")

        return jsonify({"average_score": average_score})
    
    except ValueError:
        abort(400, description="Invalid input value type")
    except ZeroDivisionError:
        abort(400, description="Division by zero")
    except TypeError:
        abort(400, description="Input values must be numeric")

