from time import time

app = Flask(__name__)
rate_limit = {}
requests_per_minute = 60

def is_valid_username(username):
    return bool(re.match(r'^[a-zA-Z0-9-]+$', username))

def rate_limit_check(user_ip):
    current_time = time()
    if user_ip not in rate_limit:
        rate_limit[user_ip] = (0, current_time)
    count, first_request_time = rate_limit[user_ip]
    if current_time - first_request_time > 60:
        rate_limit[user_ip] = (1, current_time)
    else:
        rate_limit[user_ip] = (count + 1, first_request_time)

    return rate_limit[user_ip][0] <= requests_per_minute

@app.route("/get_github_info")
def github_info():
    username = request.args.get('username')

    if not username or not is_valid_username(username):
        return "400 Bad Request", 400

    user_ip = request.remote_addr
    if not rate_limit_check(user_ip):
        return "429 Too Many Requests", 429

    try:
        response = requests.get(f'https://api.github.com/users/{username}')
        response.raise_for_status()
        user_info = json.loads(response.text)
        return jsonify(user_info)
    except requests.exceptions.RequestException:
        return "500 Internal Server Error", 500
    except KeyError:
        return "404 Not Found", 404
    except ValueError:
        return "400 Bad Request", 400

    return "500 Internal Server Error", 500

