from flask import Flask, request, Response
import base64
import os

app = Flask(__name__)

@app.route('/img/upload', methods=['POST'])
def upload_img():
    try:
        filename = request.form.get('filename')
        img = request.form.get('img')

        if not filename or not img:
            return Response("Filename and image must be provided.", status=400)

        if not isinstance(img, str) or not img.startswith('data:image/png;base64,'):
            return Response("Invalid image format.", status=400)

        img_data = img.split(',')[1]
        decoded_img = base64.b64decode(img_data)

        sanitized_filename = os.path.basename(filename)
        if sanitized_filename != filename:
            return Response("Invalid filename.", status=400)

        if len(decoded_img) > 1048576:
            return Response("File size exceeds the limit.", status=400)

        save_path = os.path.join('../assets/img/', sanitized_filename + '.png')

        with open(save_path, 'wb') as f:
            f.write(decoded_img)

        return Response("Upload successful.", status=200)
    except ValueError:
        return Response("Value error occurred.", status=400)
    except FileNotFoundError:
        return Response("File not found error occurred.", status=500)
    except Exception:
        return Response("An error occurred.", status=500)

