from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
db = SQLAlchemy(app)

# User model
class User(db.Model):
    username = db.Column(db.String(80), unique=True, nullable=False, primary_key=True)
    token = db.Column(db.String(120), nullable=False)

@app.route('/register', methods=['POST'])
def register():
    try:
        data = request.get_json()
        username = data.get("username", "")

        if not (1 <= len(username) <= 80) or not re.match("^[a-zA-Z0-9_]+$", username):
            return jsonify({"message": "Invalid username"}), 400

        if User.query.filter_by(username=username).first():
            return jsonify({"message": "User registration failed"}), 400

        token = secrets.token_hex(16)
        new_user = User(username=username, token=token)
        db.session.add(new_user)
        db.session.commit()

        return jsonify({"message": "User registered successfully", "token": token}), 201
    except Exception:
        return jsonify({"message": "Bad Request"}), 400

@app.route('/login', methods=['POST'])
def login():
    try:
        data = request.get_json()
        username = data.get("username", "")
        token = data.get("token", "")

        if User.query.filter_by(username=username, token=token).first():
            return jsonify({"message": "Authentication successful"})
        return jsonify({"message": "Authentication failed"}), 400
    except Exception:
