import os

class Manager:
    _current_privilege = 0

    def raise_privileges(self):
        self._current_privilege = 1

    def lower_privileges(self):
        self._current_privilege = 0

    def sanitize_username(self, username):
        return username.replace("..", "").replace("/", "").replace("\\", "").strip()

    def create_dir(self, username):
        username = self.sanitize_username(username)
        directory_path = os.path.join("/tmp/", username)

        if os.path.exists(directory_path) and os.path.isdir(directory_path):
            return

        self.raise_privileges()
        try:
            os.makedirs(directory_path)
        except FileExistsError:
            pass
        finally:
            self.lower_privileges()

