class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def validate_tree(root):
    if not isinstance(root, TreeNode):
        raise ValueError("Invalid tree structure")

def evaluate_expression(node):
    if node is None:
        return 0

    validate_tree(node)

    if node.left is None and node.right is None:
        return float(node.val)

    left_value = evaluate_expression(node.left)
    right_value = evaluate_expression(node.right)

    if node.val == "+":
        result = left_value + right_value
    elif node.val == "-":
        result = left_value - right_value
    elif node.val == "*":
        result = left_value * right_value
    elif node.val == "/":
        if right_value == 0:
            raise ZeroDivisionError("Division by zero")
        result = left_value / right_value
    elif node.val == "^":
        result = math.pow(left_value, right_value)
    elif node.val == "%":
        result = left_value % right_value
    else:
        raise ValueError("Invalid operation")

    if abs(result) > 10000000000.0:
        raise OverflowError("Result exceeds maximum value")

    return result

def compute_tree(root):
    try:
        return evaluate_expression(root)
    except (ValueError, ZeroDivisionError, OverflowError) as e:
        return None, str(e)

