from flask import Flask, request, jsonify
import ast
import subprocess
import contextlib
import time
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.ERROR)

ALLOWED_OPERATIONS = {'add', 'subtract', 'multiply', 'divide'}

class InvalidInputException(Exception):
    pass

class ExecutionTimeout(Exception):
    pass

class SandboxViolation(Exception):
    pass

@app.route('/execute', methods=['POST'])
def execute_data():
    try:
        if request.content_type != 'application/json':
            raise InvalidInputException("Invalid content type")

        data = request.get_json()
        code = data.get('code')

        if not validate_input(code):
            raise InvalidInputException("Input validation failed")

        execution_result = execute_in_sandbox(code)
        return jsonify({'result': execution_result})

    except InvalidInputException as e:
        logging.error(f"InvalidInputException: {str(e)}")
        return jsonify({'error': str(e)}), 400
    except ExecutionTimeout:
        return jsonify({'error': 'Execution timed out'}), 504
    except SandboxViolation:
        return jsonify({'error': 'Sandbox violation'}), 403
    except Exception as e:
        logging.error(f"Exception: {str(e)}")
        return jsonify({'error': 'Internal server error'}), 500

def validate_input(code):
    try:
        nodes = ast.parse(code, mode='eval')
        for node in ast.walk(nodes):
            if isinstance(node, ast.Name) and node.id not in ALLOWED_OPERATIONS:
                return False
        return True
    except Exception:
        return False

def execute_in_sandbox(code):
    execu = {}
    execution_start = time.time()
    with contextlib.redirect_stdout(subprocess.PIPE):
        exec(code, execu)
    execution_duration = time.time() - execution_start

    if execution_duration > 1:  # Limit execution time to 1 second
        raise ExecutionTimeout()

    return execu

if __name__ == '__main__':
    app.run()

