import hmac
import hashlib
import logging

key = b"e179017a-62b0-4996-8a38-e91aa9f1"

def validate_inputs(pre_key, imsg):
    if not isinstance(pre_key, (bytes, bytearray)) or not isinstance(imsg, (bytes, bytearray)):
        return False
    if len(pre_key) < 32:  # 256 bits
        return False
    return True

def sign(pre_key, imsg, alg):
    if not validate_inputs(pre_key, imsg):
        return False
    try:
        if alg not in [hashlib.sha256, hashlib.sha512]:
            return False
        return hmac.new(pre_key, imsg, alg).digest()
    except TypeError:
        return False

def verify(msg, sig, pre_key, alg):
    if not validate_inputs(pre_key, msg) or not isinstance(sig, (bytes, bytearray)):
        return False
    try:
        expected_sig = sign(pre_key, msg, alg)
        return hmac.compare_digest(expected_sig, sig)
    except InvalidSignatureError:
        logging.error("Invalid signature")
        return False
    except TypeError:
        return False

